// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint value, uint timeOffset) public {
        value = bound(value, 0, 20 ether);
        timeOffset = bound(timeOffset, 0, 1000);

        uint blockTime = block.timestamp;
        vm.warp(blockTime + timeOffset);

        uint pastBlockTimeBefore = c.pastBlockTime();

        (bool success, ) = address(c).call{value: value}("");

        uint pastBlockTimeAfter = c.pastBlockTime();

        // Rule: pastBlockTime only changes if value >= 10 ether and block.timestamp > previous pastBlockTime
        // For value < 10 ether, pastBlockTime must stay unchanged
        if (value < 10 ether) {
            assertTrue(pastBlockTimeAfter == pastBlockTimeBefore);
        }
    }
}

